package orders

import (
	"errors"
	"math"
)

var (
	ErrNegativeAmount = errors.New("amount and vat rate must be non-negative")
	ErrAmountOverflow = errors.New("amount overflow")
)

// TotalTTC retourne le total TTC en centimes pour un montant HT en centimes
// et un taux de TVA en pour mille (ex. 200 pour 20 %).
// La TVA est arrondie au centime le plus proche (demi vers le haut).
func TotalTTC(htCents, vatPerMille int64) (int64, error) {
	if htCents < 0 || vatPerMille < 0 {
		return 0, ErrNegativeAmount
	}
	if vatPerMille != 0 && htCents > (math.MaxInt64-500)/vatPerMille {
		return 0, ErrAmountOverflow
	}
	vat := (htCents*vatPerMille + 500) / 1000
	if htCents > math.MaxInt64-vat {
		return 0, ErrAmountOverflow
	}
	return htCents + vat, nil
}
```

